SaveSlot.methods.history:
extends Node

const PROFILE_ID: String = "local_player"
const SLOT_ID: String = "campaign"
const PAGE_SIZE: int = 8

# Assign an attached, configured GameRuntime and the load menu's ItemList.
@export var game: GameRuntime
@export var checkpoint_list: ItemList

func _ready() -> void:
    if game == null or checkpoint_list == null:
        push_error("Assign the game runtime and checkpoint list.")
        return

    var slot: SaveSlot = game.save_slot(PROFILE_ID, SLOT_ID)
    if slot == null:
        push_warning("This game has no checkpoint slot.")
        return
    var operation: GameOperation = slot.history("", "", PAGE_SIZE)
    var page: Dictionary = await operation.wait()
    if not page.get("ok", false):
        push_warning(String(page.get("message", "Could not read checkpoint history.")))
        return

    checkpoint_list.clear()
    var generations: Array = page.get("value", [])
    for generation: Dictionary in generations:
        var display: Dictionary = SavePresentation.describe(generation)
        var label: String = String(display.get("label", ""))
        if label.is_empty():
            label = "Checkpoint " + String(generation["sequence"])
        var row: int = checkpoint_list.add_item(label)
        # Keep both values so the menu can restore this exact generation.
        checkpoint_list.set_item_metadata(row, {
            "sequence": generation["sequence"],
            "id": generation["id"],
        })

SaveSlot.methods.save:
extends Node

const PROFILE: String = "local-player"
const SLOT: String = "campaign"
const CHECKPOINT_NAME: String = "Harbor checkpoint"
const LOCATION: String = "Harbor"

@export var game: GameRuntime
@export var save_status: Label

# Connect the Save button when the coordinated authority is running.
func save_harbor_checkpoint() -> void:
    if game == null or save_status == null:
        return
    var slot: SaveSlot = game.save_slot(PROFILE, SLOT)
    var request: SaveRequest = slot.save()
    request = request.named(CHECKPOINT_NAME).with_context({"location": LOCATION})
    save_status.text = "Saving checkpoint…"
    var operation: GameOperation = request.submit()
    var saved: Dictionary = await operation.wait()
    if not saved.ok:
        save_status.text = saved.message
        return
    save_status.text = "Saved " + CHECKPOINT_NAME

SceneLoadManager.methods.register_scene:
extends Node

const TRAINING_ROOM_ID: StringName = &"training_room"

# Assign a persistent node for the mounted World and select a local scene.
@export var world_container: Node
@export_file("*.tscn", "*.scn") var training_room_path: String = ""

var _loader: SceneLoadManager

func _ready() -> void:
    if world_container == null or training_room_path.is_empty():
        push_error("Assign the world container and a local training-room scene.")
        return

    _loader = SceneLoadManager.new()
    add_child(_loader)
    var container_status: Error = _loader.set_world_container(world_container)
    if container_status != OK:
        push_error(error_string(container_status))
        return

    var registered: Error = _loader.register_scene(TRAINING_ROOM_ID, training_room_path)
    if registered != OK:
        push_error(error_string(registered))
        return

    _loader.load_completed.connect(_on_load_completed)
    _loader.load_failed.connect(_on_load_failed)
    var admitted: Error = _loader.request_load(TRAINING_ROOM_ID)
    if admitted != OK:
        push_warning(error_string(admitted))

func _on_load_completed(scene_id: StringName) -> void:
    var world: Node = _loader.get_current_scene()
    if world != null:
        print("Mounted ", scene_id, " under ", world.get_parent().name)

func _on_load_failed(_scene_id: StringName, _error: int, message: String) -> void:
    push_warning(message)

SessionAuthenticator.methods._make_proof:
extends SessionAuthenticator

const CHALLENGE_BYTES: int = 32
const MAX_PROOF_BYTES: int = 4096

# Set this to your credential provider's synchronous challenge signer.
var sign_challenge: Callable

func _make_proof(peer_id: int, authority: bool, challenge: PackedByteArray) -> PackedByteArray:
    if challenge.size() != CHALLENGE_BYTES or not sign_challenge.is_valid():
        return PackedByteArray()
    var proof: PackedByteArray = sign_challenge.call(peer_id, authority, challenge)
    if proof.is_empty() or proof.size() > MAX_PROOF_BYTES:
        return PackedByteArray()
    return proof

