SteamRelayCoordinator.methods._authorize:
extends SteamRelayCoordinator

const MAX_RELAY_TICKET_BYTES: int = 4096

# The trusted backend authenticates the client and signs a ticket for the exact registration.
var fetch_relay_ticket: Callable

func _authorize_client(request: SteamRelayRequest) -> void:
    if not fetch_relay_ticket.is_valid():
        request.fail()
        return
    var ticket: PackedByteArray = await fetch_relay_ticket.call(request)
    if request.is_cancelled():
        return
    if ticket.is_empty() or ticket.size() > MAX_RELAY_TICKET_BYTES:
        request.fail()
        return
    request.authorize(ticket)

SteamRelayCoordinator.methods._register_:
extends SteamRelayCoordinator

# The authenticated backend validates the server login and stores the exact registration.
var register_with_backend: Callable

func _register_server(request: SteamRelayRequest) -> void:
    if not register_with_backend.is_valid():
        request.fail()
        return
    var accepted: bool = await register_with_backend.call(request)
    if accepted:
        # Acknowledge late success too so Crimson can withdraw a cancelled registration.
        request.registered()
    elif not request.is_cancelled():
        request.fail()

